import pandas as pd,re,numpy as np
from scipy.optimize import lsq_linear
rs=[]
for _,r in pd.read_csv('b3_supercon_target.csv').iterrows():
 d={}
 for e,n in re.findall(r'([A-Z][a-z]*)([0-9]*\.?[0-9]*)',r.composition):d[e]=d.get(e,0)+float(n or 1)
 if {'Y','Ba','Cu','O'}<=d.keys() and set(d)<=set('Y Ba Cu O Zn La Pr Ca Sr'.split()) and 6<d['O']<7.3 and 2.8<=d['Cu']<=3:
  rs.append((r.composition,d,r.target))
for cols in [['O','Zn','La','Pr'],['O','Zn','La','Pr','Ca'],['O','Zn','La','Pr','Ca','Sr']]:
 X=np.array([[1]+[(d.get(c,0)-7 if c=='O' else -d.get(c,0)) for c in cols] for _,d,_ in rs]); y=np.array([t for _,_,t in rs])
 fit=lsq_linear(X,y,bounds=(0,np.inf))
 print(cols,'n=',len(rs),'coefficients=',fit.x,'RMSE=',np.mean((X@fit.x-y)**2)**.5,'undoped O6.95:',fit.x[0]-.05*fit.x[1])
