import pandas as pd, re,numpy as np
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from sklearn.kernel_ridge import KernelRidge
from sklearn.neighbors import KNeighborsRegressor

def parse(s):
 d={}
 for e,n in re.findall(r'([A-Z][a-z]*)([0-9]*\.?[0-9]*)',s):d[e]=d.get(e,0)+float(n or 1)
 n=sum(d.values());return {e:v/n for e,v in d.items()}
df=pd.read_csv('b3_supercon_target.csv'); ds=list(map(parse,df.composition)); els=sorted(set().union(*ds))
def mat(ds):return np.array([[d.get(e,0) for e in els] for d in ds])
X=mat(ds);y=df.target.to_numpy()
names=['Y1Ba2Cu3O6.95','Y1Ba2Cu3O7','Bi2Sr2Ca1Cu2O8','Bi2Sr2Ca1Cu2O9','Bi2Sr2Ca1Cu2O10']
Z=mat(list(map(parse,names)));print(names)
for model in [ExtraTreesRegressor(n_estimators=500,random_state=42),RandomForestRegressor(n_estimators=500,random_state=42),KNeighborsRegressor(n_neighbors=3,weights='distance')]+[KernelRidge(alpha=.01,kernel='rbf',gamma=g) for g in [5,20,100]]:
 model.fit(X,y);print(str(model),np.round(model.predict(Z),2))
