import pandas as pd,re,numpy as np
from sklearn.ensemble import ExtraTreesRegressor
from sklearn.kernel_ridge import KernelRidge
D=pd.read_csv('b3_supercon_target.csv')
def parse(s):
 d={}
 for e,n in re.findall(r'([A-Z][a-z]*)([0-9]*\.?[0-9]*)',s):d[e]=d.get(e,0)+float(n or 1)
 return {e:v/sum(d.values()) for e,v in d.items()}
ds=[parse(s) for s in D.composition];els=sorted(set().union(*ds));X=np.array([[d.get(e,0) for e in els] for d in ds]);y=D.target.to_numpy()
a=ExtraTreesRegressor(n_estimators=500,random_state=42).fit(X,y);b=KernelRidge(alpha=.01,kernel='rbf',gamma=20).fit(X,y)
oxygen=np.linspace(8,8.5,10001);Z=np.zeros((len(oxygen),len(els)))
for e,n in [('Bi',2),('Sr',2),('Ca',1),('Cu',2)]:Z[:,els.index(e)]=n/(7+oxygen)
Z[:,els.index('O')]=oxygen/(7+oxygen)
p=a.predict(Z);q=b.predict(Z);k=np.argmin(abs((p+q)/2-90))
print('O stoichiometry',oxygen[k], 'ET',p[k], 'RBF',q[k], 'mean',(p[k]+q[k])/2)
for e in ['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']:
 print(e,format(Z[k,els.index(e)],'.6f'))
for x in [8,8.2]:
 d=parse('Bi2Sr2Ca1Cu2O'+str(x));z=np.array([[d.get(e,0) for e in els]])
 print('oxygen',x, 'preds',a.predict(z),b.predict(z),'fractions',d)
